import{_ as s,c as i,o as a,a2 as e}from"./chunks/framework.Dez3CbjC.js";const g=JSON.parse('{"title":"[Q004] 如何在不同端口间共享 Cookie 信息？","description":"","frontmatter":{},"headers":[],"relativePath":"HTML/04-如何在不同端口间共享 Cookie 信息？.md","filePath":"HTML/04-如何在不同端口间共享 Cookie 信息？.md"}'),o={name:"HTML/04-如何在不同端口间共享 Cookie 信息？.md"},t=e(`<h1 id="q004-如何在不同端口间共享-cookie-信息" tabindex="-1"><strong>[Q004] 如何在不同端口间共享 Cookie 信息？</strong> <a class="header-anchor" href="#q004-如何在不同端口间共享-cookie-信息" aria-label="Permalink to &quot;**[Q004] 如何在不同端口间共享 Cookie 信息？**&quot;">​</a></h1><p>在前端开发中，我们常常需要在多个端口或子应用之间共享数据。Cookie 是一个常用的机制来存储一些需要持久化的信息，比如用户的登录状态、设置等。但是，当我们的前端应用运行在不同的端口时，Cookie 是否能够共享就成为了一个问题。在这篇博客中，我们将探讨不同端口的 Cookie 信息是否共享，以及如何解决这个问题。</p><h2 id="_1-不同端口的-cookie-是否共享" tabindex="-1"><strong>1. 不同端口的 Cookie 是否共享？</strong> <a class="header-anchor" href="#_1-不同端口的-cookie-是否共享" aria-label="Permalink to &quot;**1. 不同端口的 Cookie 是否共享？**&quot;">​</a></h2><p>首先，我们来回答一个简单的问题：<code>localhost:3000</code> 和 <code>localhost:5000</code> 之间的 Cookie 是否共享？答案是：<strong>不共享</strong>。</p><p>这是因为，Cookie 是与 <strong>域名</strong> 和 <strong>端口</strong> 绑定的。虽然它们都指向 <code>localhost</code>，但由于端口号不同，浏览器会认为它们是两个不同的来源，从而不会共享 Cookie。浏览器会将 <code>localhost:3000</code> 的 Cookie 限制在端口 3000 上，而不会在端口 5000 上发送。</p><h2 id="_2-如何在不同端口之间共享-cookie" tabindex="-1"><strong>2. 如何在不同端口之间共享 Cookie？</strong> <a class="header-anchor" href="#_2-如何在不同端口之间共享-cookie" aria-label="Permalink to &quot;**2. 如何在不同端口之间共享 Cookie？**&quot;">​</a></h2><p>虽然默认情况下不同端口的 Cookie 不共享，但我们可以通过一些设置让它们共享。这里有几种常见的做法：</p><h3 id="设置相同的-domain-属性" tabindex="-1"><strong>设置相同的 <code>Domain</code> 属性</strong> <a class="header-anchor" href="#设置相同的-domain-属性" aria-label="Permalink to &quot;**设置相同的 \`Domain\` 属性**&quot;">​</a></h3><p>在设置 Cookie 时，可以通过指定 <code>domain</code> 属性来让不同端口共享同一个 Cookie。只需要将 <code>domain</code> 设置为 <code>.localhost</code>（注意前面的点），这样 Cookie 就会在 <code>localhost</code> 下的所有端口之间共享。代码示例如下：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">document.cookie </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;name=value; domain=.localhost; path=/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>这样，<code>localhost:3000</code> 和 <code>localhost:5000</code> 都会发送这个 Cookie，前提是浏览器支持并允许这种设置。</p><h3 id="使用跨域请求与-cors" tabindex="-1"><strong>使用跨域请求与 CORS</strong> <a class="header-anchor" href="#使用跨域请求与-cors" aria-label="Permalink to &quot;**使用跨域请求与 CORS**&quot;">​</a></h3><p>如果你的应用需要跨域请求，而不仅仅是不同端口间的请求，你还可以使用 <strong>跨域资源共享（CORS）</strong> 机制来允许不同源之间的 Cookie 共享。在这种情况下，需要在服务器端设置 <code>Access-Control-Allow-Origin</code> 和 <code>Access-Control-Allow-Credentials</code> 头部。客户端则需要设置 <code>withCredentials: true</code>。</p><p>服务器端的设置（比如 Node.js + Express）：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Access-Control-Allow-Origin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:3000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Access-Control-Allow-Credentials&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>客户端的请求：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:5000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  credentials: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;include&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 发送带有凭证（cookie）的信息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data));</span></span></code></pre></div><p>通过这种方式，不同端口的应用就能够共享 Cookie，前提是满足 CORS 的要求。</p><h2 id="_3-注意事项" tabindex="-1"><strong>3. 注意事项</strong> <a class="header-anchor" href="#_3-注意事项" aria-label="Permalink to &quot;**3. 注意事项**&quot;">​</a></h2><ul><li><strong>安全性</strong>：使用跨端口或跨域共享 Cookie 时，要特别注意 Cookie 的安全性。建议设置 <code>Secure</code> 属性，确保 Cookie 只会在 HTTPS 请求中发送。还可以设置 <code>HttpOnly</code>，防止 JavaScript 访问 Cookie，从而增强安全性。</li><li><strong>跨站请求伪造（CSRF）</strong>：当启用 <code>withCredentials</code> 时，可能会遇到 CSRF 攻击的风险。为防范这种攻击，可以使用 CSRF token 或其他安全措施。</li></ul><h2 id="_4-小结" tabindex="-1"><strong>4. 小结</strong> <a class="header-anchor" href="#_4-小结" aria-label="Permalink to &quot;**4. 小结**&quot;">​</a></h2><p>尽管不同端口的应用默认不能共享 Cookie，但我们可以通过设置 <code>domain</code> 或使用 CORS 等技术来实现共享。这样不仅方便了多个前端应用间的数据传递，也为开发者提供了更多的灵活性。</p>`,22),n=[t];function h(l,k,p,d,r,c){return a(),i("div",null,n)}const C=s(o,[["render",h]]);export{g as __pageData,C as default};
